/* 1. ГЕНЕРАЦИЯ КАРТОЧКИ */
function createCard(item) {
    const specialClass = item.special ? 'special' : '';
   let typeLabel = '';

if (item.type === 'vuz') {
    typeLabel = 'ВУЗ';
} else if (item.type === 'college') {
    typeLabel = 'Колледж';
} else if (item.type === 'vocational_school') {
    typeLabel = 'ПРОФ.ЛИЦЕЙ';
} else {
    typeLabel = 'Заведение'; 
}

const priceText = item.type === 'vocational_school' ? 'Бюджет / Контракт' : (item.price === 0 ? 'Бесплатно (Госзаказ)' : '~ ' + item.price.toLocaleString() + ' сом/год');
    
return '<div class="feature-card ' + specialClass + '">' +
        '<div class="card-header">' +
            '<span class="badge ' + item.type + '">' + typeLabel + '</span>' +
            '<i class="fas ' + item.icon + '"></i>' +
        '</div>' +
        '<div class="card-body">' +
            '<h3>' + item.name + '</h3>' +
            '<p class="univ-name">' + item.univ + '</p>' +
            '<div class="stats">' +
                '<div class="stat-item"><span>Срок обучения:</span><strong>' + item.time + '</strong></div>' +
                '<div class="stat-item"><span>Мин. балл ОРТ:</span><strong>' + item.budget + '</strong></div>' +
            '</div>' +
            '<button class="map-btn" onclick="window.open(\'' + item.map + '\', \'_blank\')">' +
                '<i class="fas fa-map-marker-alt"></i> Найти на карте' +
            '</button>' +
        '</div>' +
        '<div class="card-footer">' +
            '<p class="price">' + priceText + '</p>' +
        '</div>' +
    '</div>';
}

/* 2. ГЛОБАЛЬНЫЕ ПЕРЕМЕННЫЕ */
window.currentType = 'all';
window.currentSphere = 'all';
window.currentQuery = '';

function normalizeText(value) {
    return (value || '').toString().toLowerCase().trim();
}

/* 3. УНИВЕРСАЛЬНЫЙ РЕНДЕР */
window.renderList = function() {
    var searchContainer = document.getElementById('schoolsContainer');
    var catalogContainer = document.getElementById('all-list');
    var targetContainer = catalogContainer || searchContainer;

    if (!targetContainer) return;

    var scoreInput = document.getElementById('userScore');
    var score = scoreInput ? parseInt(scoreInput.value) : NaN;
    var queryInput = document.getElementById('professionQuery');
    var query = queryInput ? normalizeText(queryInput.value) : normalizeText(window.currentQuery);

    var isSearchPage = !!searchContainer;

    var filtered = finalDatabase.filter(function(item) {
        var matchType = (window.currentType === 'all' || item.type === window.currentType);
        var matchSphere = (window.currentSphere === 'all' || item.sphere === window.currentSphere);
        var searchableText = normalizeText([item.name, item.univ, item.cat, item.sphere].join(' '));
        var matchQuery = !query || searchableText.indexOf(query) !== -1;

        // если это страница поиска И введён балл
        if (isSearchPage && !isNaN(score) && score > 0) {
            return matchType && matchSphere && matchQuery && score >= item.budget;
        }

        return matchType && matchSphere && matchQuery;
    });

    filtered.sort((a, b) => b.budget - a.budget);

    targetContainer.innerHTML = filtered.length
        ? filtered.map(createCard).join('')
        : '<p style="grid-column: 1/-1; text-align: center; padding: 50px;">Ничего не найдено. Попробуйте изменить фильтры.</p>';
};

/* 4. ФУНКЦИИ КНОПОК */
// Функция для фильтров в КАТАЛОГЕ (universities.html)
window.filterCatalog = function(type, event) {
    window.currentType = type;
    var parent = event.currentTarget.parentElement;
    parent.querySelectorAll('.tab-btn').forEach(btn => btn.classList.remove('active'));
    event.currentTarget.classList.add('active');
    window.renderList();
};

window.filterByCategory = function(sphere, event) {
    window.currentSphere = sphere;
    var parent = event.currentTarget.parentElement;
    parent.querySelectorAll('.tab-btn').forEach(btn => btn.classList.remove('active'));
    event.currentTarget.classList.add('active');
    window.renderList();
};

window.setProfessionQuery = function(value) {
    window.currentQuery = normalizeText(value);
    window.renderList();
};

// Функция для страницы ПОИСКА (search.html)
window.filterSchools = function() {
    var title = document.getElementById('resultsTitle');
    if (title) title.style.display = 'block';
    window.renderList();
    if (title) title.scrollIntoView({ behavior: 'smooth' });
};

// Функции для кнопок на странице ПОИСКА
window.setSearchType = function(type, element) {
    window.currentType = type;
    element.parentElement.querySelectorAll('.tab-btn').forEach(btn => btn.classList.remove('active'));
    element.classList.add('active');
};

window.setSearchSphere = function(sphere, element) {
    window.currentSphere = sphere;
    element.parentElement.querySelectorAll('.tab-btn').forEach(btn => btn.classList.remove('active'));
    element.classList.add('active');
};

window.setSearchSphere = function(sphere, element) {
    window.currentSphere = sphere;
    element.parentElement.querySelectorAll('.tab-btn').forEach(btn => btn.classList.remove('active'));
    element.classList.add('active');
    
    if (document.getElementById('all-list') || document.getElementById('userScore').value !== '') {
        window.renderList();
    }
};

/* 5. КНОПКА "НАЙТИ ВАРИАНТЫ" (Для Search.html) */
window.filterSchools = function() {
    var title = document.getElementById('resultsTitle');
    if (title) title.style.display = 'block';
    window.renderList();
    if (title) title.scrollIntoView({ behavior: 'smooth' });
};

/* 6. ЗАПУСК ПРИ ЗАГРУЗКЕ */
document.addEventListener('DOMContentLoaded', function() {
    // В каталоге грузим сразу, в поиске — ждем ввода
    if (document.getElementById('all-list')) {
        window.renderList();
    }
});

